public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            sb.append(coord[i]).append(',');
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<int[]>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) {
            // Invalid path length; skip or handle error
            continue;
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = coordKey.apply(a);
        String bKey = coordKey.apply(b);
        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(a);
    }

    // BFS
    java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(start);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        String curKey = coordKey.apply(current);
        java.util.List<int[]> neighbors = adj.getOrDefault(curKey, java.util.Collections.emptyList());
        for (int[] neighbor : neighbors) {
            String neighKey = coordKey.apply(neighbor);
            if (!visited.contains(neighKey)) {
                if (neighKey.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighKey);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

