}

private int dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple) {
    int total = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int childTime = dfs(child, node, graph, hasApple);
        if (childTime > 0 || hasApple[child]) {
            total += childTime + 2;
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = freq.firstEntry();
        char last = entry.getKey();
        sb.append(last);
        if (entry.getValue() == 1) {
            freq.remove(last);
        } else {
            freq.put(last, entry.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = freq.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            sb.append(last);
            if (next.getValue() == 1) {
                freq.remove(last);
            } else {
                freq.put(last, next.getValue() - 1);
            }
        }
        if (freq.isEmpty()) break;
        // Descending phase
        entry = freq.lastEntry();
        last = entry.getKey();
        sb.append(last);
        if (entry.getValue() == 1) {
            freq.remove(last);
        } else {
            freq.put(last, entry.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = freq.lowerEntry(last);
            if (next == null) break;
            last = next.getKey();
            sb.append(last);
            if (next.getValue() == 1) {
                freq.remove(last);
            } else {
                freq.put(last, next.getValue() - 1);
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sets = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) sets[i] = new HashSet<>();
    sets[0].add(0);
    for (int i = 0; i < n; i++) {
        int num = nums[i];
        int upper = Math.min(i + 1, maxK);
        for (int k = upper; k >= 1; k--) {
            for (int sum : sets[k - 1]) {
                sets[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (int) ((totalSum * k) / n);
        if (sets[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

