public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskLimit = total - 1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                count++;
                if (count == total) return true;
            }
        }
    }
    return false;
}

