public int minInsertions(String s) {
    int balance = 0;   // number of unmatched '('
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an extra '(' before this ')'
                insertions++;
            } else {
                balance--;
            }
        }
    }
    // each remaining unmatched '(' needs one ')'
    insertions += balance;
    return insertions;
}

