public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = nums[0];
    int minSum = nums[0];
    int currentMax = nums[0];
    int currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    // Generate Fibonacci numbers up to k
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) break;
        fib.add(next);
    }
    int count = 0;
    int remaining = k;
    // Greedy: subtract largest Fibonacci number <= remaining
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Collect all factors of n
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    // Sort factors in ascending order
    java.util.Collections.sort(factors);
    // Check if k is within bounds
    if (k <= 0 || k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // one is lowercase, the other uppercase of same letter
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

