private void dfs(String s, int idx, java.util.Set<String> used, int[] max) {
    if (idx == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int i = idx; i < s.length(); i++) {
        String sub = s.substring(idx, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, i + 1, used, max);
            used.remove(sub);
        }
    }
}

