public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // Initialize all characters to 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // extra value needed beyond all 'a's
    // Distribute the remaining value from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // maximum we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

