public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        if (d <= high) {
            queue.offer((long) d);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    int count = 0;
    for (int factor = 1; factor <= n; factor *= 10) {
        int lower = n % factor;
        int current = (n / factor) % 10;
        int higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return count;
}

