public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long abs = negative ? -(long) n : n;
    StringBuilder sb = new StringBuilder();
    while (abs > 0) {
        long part = abs % 1000;
        abs /= 1000;
        if (abs > 0) {
            sb.insert(0, String.format("%03d", part));
            sb.insert(0, '.');
        } else {
            sb.insert(0, Long.toString(part));
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    java.util.HashSet<Integer> squares = new java.util.HashSet<>();
    for (int i = 1; i * i <= maxSum; i++) {
