public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    // push sentinel index -1 to simplify width calculation
    stack[++top] = -1;
    for (int i = 0; i < n; i++) {
        while (top > 0 && heights[stack[top]] > heights[i]) {
            int height = heights[stack[top--]];
            int width = i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top > 0) {
        int height = heights[stack[top--]];
        int width = n - stack[top] - 1;
        int area = height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) return -1;
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find the first index from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }
    // Find the smallest digit on right side of i that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i+1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // In case the number exceeds int range (shouldn't happen with same digits)
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] arr = new char[n];
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    backtrack(0, n, arr, pairs, result);
    Collections.sort(result);
    return result;
}

private static void backtrack(int i, int n, char[] arr, char[][] pairs, List<String> result) {
    if (i >= (n + 1) / 2) {
        result.add(new String(arr));
        return;
    }
    if (i == n - 1 - i) { // middle position for odd length
        for (char c : new char[]{'0', '1', '8'}) {
            arr[i] = c;
            backtrack(i + 1, n, arr, pairs, result);
        }
    } else {
        for (char[] pair : pairs) {
            if (i == 0 && pair[0] == '0' && n > 1) {
                continue; // no leading zero for length > 1
            }
            arr[i] = pair[0];
            arr[n - 1 - i] = pair[1];
            backtrack(i + 1, n, arr, pairs, result);
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check that all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute the area of the triangle (cross product)
    int area2 = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = (long) current * 10 + d;
        if (next > n) {
            break; // further digits will only increase the value
        }
        dfs((int) next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim leading/trailing spaces to avoid empty words at ends
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        return "";
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder rev = new StringBuilder(word).reverse();
        result.append(rev);
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
